var RX_BODY = window.RX_BODY || {};

RX_BODY['montelukast'] = {
  what: {
    ar: 'المونتيلوكاست دواء وقائي للربو وحساسية الأنف، يُصرف بوصفة على شكل أقراص للبلع وأقراص للمضغ وحبيبات للأطفال الصغار. ينتمي إلى فصيلة تُسمّى مضادات مستقبل اللوكوترايين، واللوكوترايين مادة يفرزها الجسم في الحساسية فتضيّق الشعب وتزيد المخاط والالتهاب والتورّم. يعمل المونتيلوكاست بحجب هذه المادة عن مستقبلها، فيقلّ الضيق والالتهاب مع الوقت. وينبغي أن يُفهم أنه دواء يُؤخذ بانتظام للوقاية لا للإنقاذ، فهو لا يفتح الصدر بسرعة ولا يُغني عن بخّاخ النوبة، وأثره يبني حماية على مدى الأيام لا الدقائق.',
    en: 'Montelukast is a preventive medicine for asthma and nasal allergy, prescription-only as swallow tablets, chewable tablets and granules for young children. It belongs to a family called leukotriene receptor antagonists; leukotriene is a substance the body releases in allergy that narrows the airways and increases mucus, inflammation and swelling. Montelukast blocks this substance from its receptor, so narrowing and inflammation ease over time. It should be understood as a medicine taken regularly for prevention, not for rescue: it does not open the chest quickly and does not replace a reliever inhaler, and its effect builds protection over days rather than minutes.'
  },
  why: {
    ar: 'يوصف للوقاية طويلة الأمد من الربو والسيطرة عليه، وخاصة حين لا يكفي البخّاخ الوقائي وحده أو حين ترافق الربوَ حساسيةُ أنف واضحة، فيعالج المشكلتين معاً. وله دور معروف في الربو الذي يثيره المجهود البدني، إذ يقي من ضيق النفس المصاحب للرياضة. ويُستعمل كذلك في حساسية الأنف الموسمية والدائمة لتخفيف العطاس والزكام والحكّة والانسداد. وهو مفيد بوجه خاصّ عند الأطفال الذين يصعب عليهم استعمال البخّاخات، ولمن يعانون الحساسية والربو في آن. ولا يفيد في نوبة ربو قائمة تحتاج علاجاً سريعاً، ولا يُبدأ به عند اشتداد الأعراض فجأة.',
    en: 'It is prescribed for long-term prevention and control of asthma, especially when a preventer inhaler alone is not enough or when asthma comes with clear nasal allergy, so it treats both problems together. It has a known role in exercise-induced asthma, guarding against the breathlessness that accompanies exertion. It is also used in seasonal and perennial nasal allergy to ease sneezing, running, itching and blockage. It is particularly helpful in children who struggle with inhalers, and for those who have allergy and asthma at once. It does nothing for an ongoing asthma attack that needs quick treatment, and it is not started when symptoms suddenly worsen.'
  },
  how: {
    ar: 'حين يتعرّض الجسم لمثير الحساسية تُطلق خلاياه مواد وسيطة من بينها اللوكوترايينات، وهي من أقوى ما يضيّق العضلة حول الشعب ويستدعي المخاط ويجذب خلايا الالتهاب ويجعل جدار المجرى يتورّم. لهذه المواد أبواب تلتصق بها على الخلايا تُسمّى المستقبلات، ومن خلالها تحدث كل هذه التأثيرات. يجلس المونتيلوكاست على هذا الباب فيغلقه في وجه اللوكوترايين، فلا تجد المادة سبيلاً إلى إحداث الضيق والالتهاب. وهذا الطريق يفسّر لماذا يعمل الدواء في الربو التحسّسي وحساسية الأنف معاً، ولماذا يحتاج انتظاماً حتى تظهر فائدته الكاملة، فهو يمنع سلسلة تُبنى ببطء لا يوقف نوبة قائمة.',
    en: 'When the body meets an allergy trigger, its cells release mediators including leukotrienes, among the most powerful at tightening the muscle around the airways, summoning mucus, drawing in inflammatory cells and making the airway wall swell. These substances have doors they attach to on cells called receptors, through which all these effects happen. Montelukast sits on that door and closes it in the face of leukotriene, so the substance finds no way to cause narrowing and inflammation. This pathway explains why the medicine works in allergic asthma and nasal allergy together, and why it needs regularity before its full benefit shows, since it prevents a slowly built chain rather than stopping an attack in progress.'
  },
  effects: {
    ar: 'أكثر آثاره شيوعاً صداع وألم في البطن، وقد يظهر عطش أو حرارة خفيفة أو أعراض شبيهة بالزكام والسعال، وطفح جلدي بسيط أحياناً. وكثير من الناس يأخذه مدداً طويلة دون شكوى تُذكر. لكن أهمّ ما يجب الانتباه له ليس أثراً جسدياً بل نفسياً وسلوكياً، وهذا ما دفع السلطة الدوائية إلى وضع تحذير خاصّ في نشرته، وهو مفصّل في الحقل التالي. وعند الأطفال قد يلاحظ الأهل تغيّراً في النوم أو أحلاماً مزعجة أو فرط حركة، فينبغي ألّا تُهمل هذه الملاحظات بل تُنقل إلى الطبيب لأنها قد تكون من الدواء لا من الطفل.',
    en: 'Its commonest effects are headache and abdominal pain, and thirst, a mild fever, cold-like symptoms and cough may appear, with an occasional mild rash. Many people take it for long periods without notable complaint. But the most important thing to watch is not a physical effect but a mental and behavioural one, which is what led the drug authority to place a special warning in its leaflet, set out in the next field. In children, parents may notice a change in sleep, unpleasant dreams or overactivity, and these observations should not be dismissed but reported to the doctor, since they may come from the medicine rather than the child.'
  },
  warning: {
    ar: 'أخطر ما في هذا الدواء آثاره على المزاج والسلوك، فقد وضعت السلطة الأمريكية تحذيراً مؤطّراً بعده. توقّف عن الدواء وراجع الطبيب فوراً إن ظهر قلق شديد أو اكتئاب أو تهيّج أو عدوانية أو اضطراب نوم أو كوابيس أو هلوسة أو رعشة، وخاصة أي فكرة أو حديث عن إيذاء النفس، فهذه حالة طوارئ لا تنتظر موعداً. واطلب الإسعاف عند تورّم الوجه أو الشفتين أو اللسان أو الحلق أو ضيق نفس مفاجئ أو طفح متفقّع، فقد يكون تحسّساً شديداً. وراجع كذلك عند خدر أو وخز في الأطراف أو جيوب أنفية ملتهبة مع طفح، ولا تعتمد عليه أبداً لإيقاف نوبة ربو حادّة، بل استعمل بخّاخ الإنقاذ واطلب المساعدة.',
    en: 'The gravest thing about this medicine is its effects on mood and behaviour, after which the American authority placed a boxed warning. Stop the medicine and see a doctor at once if severe anxiety, depression, agitation, aggression, disturbed sleep, nightmares, hallucinations or tremor appear, and above all any thought or talk of self-harm, which is an emergency that does not wait for an appointment. Call an ambulance for swelling of the face, lips, tongue or throat, sudden breathlessness or a blistering rash, which may be a severe allergy. Seek review too for numbness or tingling in the limbs or inflamed sinuses with a rash, and never rely on it to stop an acute asthma attack; use the rescue inhaler and get help.'
  },
  interact: {
    ar: 'تعارضاته أقلّ مما يظنّ كثيرون، لكنها موجودة. أهمّها الفينوباربيتال وبعض أدوية الصرع ومضادّ حيوي كالريفامبيسين، فهي تسرّع كسر المونتيلوكاست في الكبد فيقلّ مستواه وتضعف فائدته، وقد يحتاج الطبيب إلى تقدير ذلك. وينبغي ألّا يُفهم من أخذه أن أدوية الربو الأخرى تُوقف: فهو يُضاف إلى البخّاخ الوقائي وبخّاخ الإنقاذ لا يحلّ محلّهما، وإيقاف الكورتيزون الوقائي فجأة بحجّة البدء به خطأ قد يفجّر نوبة. أخبر الصيدلي بكل ما تأخذه من موصوف وغير موصوف وأعشاب، فالأهمّ أن تُعرف الأدوية التي تُسرّع كسره حتى تُوازن الخطّة.',
    en: 'Its interactions are fewer than many suppose, but they exist. The chief ones are phenobarbital, some epilepsy medicines and an antibiotic such as rifampicin, which speed the breakdown of montelukast in the liver so its level falls and its benefit weakens, and the doctor may need to account for that. Taking it should not be read as stopping other asthma medicines: it is added to the preventer and reliever inhalers, not a substitute for them, and suddenly stopping a preventer steroid in order to begin it is a mistake that may set off an attack. Tell the pharmacist everything you take, prescribed or not, and any herbs, since what matters most is knowing the drugs that speed its breakdown so the plan can be balanced.'
  },
  avoid: {
    ar: 'لا يأخذه من تحسّس سابقاً منه. ويُستعمل بحذر شديد ومراقبة قريبة عند من له تاريخ نفسي كاكتئاب أو قلق أو أفكار إيذاء النفس، لأنه قد يوقظ هذه الحالات أو يفاقمها، فيوازن الطبيب فائدته بخطره في كل شخص على حدة. وأقراص المضغ منها ما يحتوي محلّياً على مادة الأسبارتام، فتُتجنّب في مرض بيلة الفينيل كيتون الوراثي. وفي الحمل والرضاعة لا يُبدأ به عادة إلا إذا رأى الطبيب أن فائدته للأمّ تفوق أيّ احتمال، ويُفضّل عندها الاستمرار على علاج معروف الأمان سبق ضبط الربو به. ومرضى الكبد الشديد يحتاجون تقديراً خاصّاً. وأيّ تغيّر نفسي مفاجئ سبب لإيقافه ومراجعة الطبيب.',
    en: 'It is not for anyone who has reacted to it before. It is used with great caution and close watching in anyone with a psychiatric history such as depression, anxiety or thoughts of self-harm, because it may awaken or worsen these states, so the doctor weighs its benefit against its risk in each person. Some chewable tablets are sweetened with aspartame, so they are avoided in the inherited disease phenylketonuria. In pregnancy and breastfeeding it is usually not started unless the doctor judges its benefit to the mother outweighs any possibility, and continuing a treatment of known safety that already controlled the asthma is preferred. People with severe liver disease need a special judgement. Any sudden mental change is a reason to stop it and see the doctor.'
  },
  updated: '2026-09-25',
  src: [
    'https://medlineplus.gov/druginfo/meds/a600014.html',
    'https://www.nhs.uk/medicines/montelukast/'
  ]
};

RX_BODY['tamsulosin'] = {
  what: {
    ar: 'التامسولوسين دواء يُصرف بوصفة كبسولات، ينتمي إلى حاصرات ألفا، ويُستعمل أساساً لتخفيف أعراض تضخّم البروستاتا الحميد عند الرجال. البروستاتا غدّة تحيط بمجرى البول عند مخرج المثانة، وحين تكبر مع العمر تعصر المجرى وتشدّ العضلة حوله فيصعب التبوّل. يرخي التامسولوسين هذه العضلة في عنق المثانة والبروستاتا فيتّسع المجرى ويسهل خروج البول، لكنه لا يصغّر الغدّة نفسها. لذلك يحسّن الأعراض بسرعة نسبياً دون أن يعالج سبب التضخّم، وقد يجمعه الطبيب مع دواء آخر يصغّر الغدّة فعلاً حين يكون التضخّم كبيراً.',
    en: 'Tamsulosin is a prescription capsule of the alpha-blocker family, used mainly to ease the symptoms of benign prostate enlargement in men. The prostate is a gland surrounding the urinary passage at the bladder outlet, and as it enlarges with age it squeezes the passage and tightens the muscle around it, making urination difficult. Tamsulosin relaxes this muscle in the bladder neck and prostate so the passage widens and urine flows more easily, but it does not shrink the gland itself. It therefore improves symptoms fairly quickly without treating the cause of the enlargement, and the doctor may combine it with another drug that actually shrinks the gland when the enlargement is large.'
  },
  why: {
    ar: 'يوصف لتخفيف أعراض تضخّم البروستاتا الحميد: ضعف تيّار البول وتقطّعه، والتردّد قبل بدئه، والإحساس بعدم إفراغ المثانة كاملة، وكثرة التبوّل ليلاً، والإلحاح المفاجئ. وهو يريح المريض دون جراحة في كثير من الحالات المتوسّطة. ويُستعمل أحياناً بقرار الطبيب لتسهيل مرور حصاة عالقة في الحالب السفلي، لأنه يرخي عضلته فتنزلق الحصاة أيسر. لكنه لا يعالج عدوى المسالك ولا سرطان البروستاتا ولا فرط نشاط المثانة بمفرده، ولا يُستعمل عند المرأة لهذه الدواعي. والغاية منه راحة التبوّل لا شفاء الغدّة، فمتابعة الطبيب تبقى ضرورية لأن التضخّم قد يتقدّم.',
    en: 'It is prescribed to ease the symptoms of benign prostate enlargement: a weak, interrupted stream, hesitancy before it starts, a sense of not emptying the bladder fully, frequent night-time urination and sudden urgency. It relieves many moderate cases without surgery. It is sometimes used, on a doctor\'s decision, to help a stone lodged in the lower ureter pass, because it relaxes that muscle so the stone slips through more easily. But it does not treat urinary infection, prostate cancer or an overactive bladder on its own, and it is not used in women for these purposes. Its aim is comfortable urination, not cure of the gland, so follow-up remains necessary because the enlargement may progress.'
  },
  how: {
    ar: 'في عنق المثانة والبروستاتا مستقبلات من نوع ألفا، إذا نُبّهت شدّت العضلة الملساء وضيّقت المجرى. يجلس التامسولوسين على هذه المستقبلات فيمنع تنبيهها، فترتخي العضلة ويتّسع المجرى ويخرج البول بأقلّ مقاومة. وهو مصمّم ليعمل على مستقبلات المسالك أكثر من مستقبلات الأوعية الدموية، ولهذا أثره في ضغط الدم أخفّ من حاصرات ألفا الأقدم، لكنه لا ينعدم. وهذا يفسّر لماذا يحسّن التبوّل بسرعة دون أن يصغّر الغدّة، ولماذا يظلّ الدوار وهبوط الضغط عند الوقوف من آثاره الممكنة، خاصة مع أول الكبسولات قبل أن يعتاد الجسم عليه.',
    en: 'In the bladder neck and prostate there are receptors of the alpha type; when stimulated they tighten the smooth muscle and narrow the passage. Tamsulosin sits on these receptors and prevents their stimulation, so the muscle relaxes, the passage widens and urine flows with less resistance. It is designed to act on urinary receptors more than on blood-vessel receptors, so its effect on blood pressure is milder than the older alpha-blockers, though not absent. This explains why it improves urination quickly without shrinking the gland, and why dizziness and a drop in blood pressure on standing remain possible effects, especially with the first capsules before the body grows used to it.'
  },
  effects: {
    ar: 'أشيع آثاره الدوار وخفّة الرأس، خاصة عند القيام من الجلوس أو النوم فجأة، ولهذا يُنصح بالتمهّل في الحركة أول أيام العلاج. ومن آثاره المميّزة جفاف القذف أو قلّته أو رجوعه إلى المثانة بدل خروجه، وهذا لا يضرّ الصحّة وإن أقلق بعض الرجال، ويزول غالباً بإيقاف الدواء. وقد يسبّب صداعاً وضعفاً وسيلاناً أو انسداداً في الأنف وخفقاناً. وبعض الناس يشعر بنعاس أو اضطراب في النوم. وهذه الآثار في مجملها محتمَلة وتخفّ مع الاستمرار، والفارق بينها وبين ما يستدعي التوقّف مذكور في الحقل التالي، وأخطره أثرٌ يخصّ عين من ينتظر عملية ماء أبيض.',
    en: 'Its commonest effects are dizziness and light-headedness, especially on rising suddenly from sitting or sleeping, so moving slowly in the first days is advised. A characteristic effect is dry, reduced or backward ejaculation into the bladder instead of outward; this does not harm health though it troubles some men, and it usually goes when the drug is stopped. It may cause headache, weakness, a runny or blocked nose and palpitations. Some people feel drowsy or sleep poorly. On the whole these effects are tolerable and ease with continuation, and the difference between them and what demands stopping is in the next field, the most serious of which concerns the eye of anyone awaiting a cataract operation.'
  },
  warning: {
    ar: 'أخبر جرّاح العيون والطبيب أنك تأخذ هذا الدواء قبل أيّ عملية ماء أبيض أو ماء أزرق، حتى لو توقّفت عنه، فقد يجعل حدقة العين رخوة أثناء العملية فتحدث مشكلة تُعرف بمتلازمة القزحية المرتخية، ومعرفة الجرّاح بها مسبقاً تمنع أذاها. واطلب الإسعاف عند تورّم الوجه أو الشفتين أو اللسان أو الحلق أو ضيق نفس أو طفح متفقّع، فقد يكون تحسّساً شديداً. وتوقّف وراجع فوراً عند إغماء أو دوار شديد يسقطك، وعند انتصاب مؤلم يدوم طويلاً فهذه حالة طارئة تهدّد العضو. وراجع الطبيب عند خفقان قويّ متكرّر أو ألم صدر جديد. ولا تقُد ولا تشغّل آلة حتى تعرف كيف يؤثّر فيك أول أيامه.',
    en: 'Tell the eye surgeon and doctor that you take this medicine before any cataract or glaucoma operation, even if you have stopped it, because it can make the pupil floppy during surgery, a problem called intraoperative floppy iris syndrome, and the surgeon\'s prior knowledge prevents its harm. Call an ambulance for swelling of the face, lips, tongue or throat, breathlessness or a blistering rash, which may be a severe allergy. Stop and seek review at once for fainting or dizziness severe enough to make you fall, and for a painful erection that lasts a long time, an emergency that threatens the organ. See the doctor for repeated strong palpitations or new chest pain. Do not drive or operate machinery until you know how its first days affect you.'
  },
  interact: {
    ar: 'أهمّ تعارضاته اجتماعه مع أدوية أخرى تخفض الضغط أو ترخي الأوعية، مثل خافضات الضغط ومثبّطات إنزيم PDE5 كالسيلدينافيل المستعملة لضعف الانتصاب، فقد يهبط الضغط اجتماعاً فيشتدّ الدوار والإغماء، ويبدأ الطبيب بحذر ويباعد التوقيت. وترفع بعض مضادات الفطريات ومضادات الفيروسات ومضاد حيوي كالكلاريثرومايسين مستوى التامسولوسين في الدم لأنها تعطّل إنزيماً يكسره، فيزيد أثره الخافض للضغط. ويُنتبع للجمع مع حاصرات ألفا أخرى أو مدرّات البول. أخبر الصيدلي بكل دواء تأخذه ولو لضعف الانتصاب، فكثير من الرجال يجمع الدوائين دون أن يذكر ذلك.',
    en: 'Its most important interaction is combining with other medicines that lower blood pressure or relax vessels, such as antihypertensives and PDE5 inhibitors like sildenafil used for erectile dysfunction, because blood pressure may fall together and worsen dizziness and fainting, so the doctor starts cautiously and spaces the timing. Some antifungals, antivirals and an antibiotic such as clarithromycin raise the level of tamsulosin in the blood by blocking an enzyme that breaks it down, increasing its pressure-lowering effect. Care is needed in combining it with other alpha-blockers or diuretics. Tell the pharmacist every medicine you take, even for erectile dysfunction, since many men combine the two without mentioning it.'
  },
  avoid: {
    ar: 'لا يأخذه من تحسّس منه. وهو دواء للرجال في تضخّم البروستاتا، ولا يُستعمل عند النساء ولا الأطفال لهذا الغرض. ويُستعمل بحذر عند من يميل ضغطه إلى الهبوط عند الوقوف، وعند مرضى الكبد أو الكلى الشديد الذين قد يحتاجون تقديراً خاصاً. ومن ينتظر عملية ماء أبيض أو أزرق يجب أن يُخبر جرّاحه قبلها. وقبل البدء به يستبعد الطبيب سرطان البروستاتا وعدوى المسالك، لأن أعراضهما قد تشبه التضخّم الحميد فلا يُغطّى مرض خطير بدواء يخفّف الأعراض وحدها. ومن أصابه إغماء مع أدوية مشابهة من قبل ينبّه طبيبه. والقيادة تُؤجّل حتى يُعرف أثره في الأيام الأولى.',
    en: 'It is not for anyone allergic to it. It is a medicine for men with prostate enlargement, and it is not used in women or children for this purpose. It is used with caution in anyone whose blood pressure tends to drop on standing, and in people with severe liver or kidney disease who may need a special judgement. Anyone awaiting a cataract or glaucoma operation must tell the surgeon beforehand. Before starting it the doctor rules out prostate cancer and urinary infection, because their symptoms may resemble benign enlargement, so a serious disease is not masked by a drug that only eases symptoms. Anyone who fainted with similar medicines before should alert the doctor. Driving is postponed until its effect in the first days is known.'
  },
  updated: '2026-09-25',
  src: [
    'https://medlineplus.gov/druginfo/meds/a698012.html',
    'https://www.nhs.uk/medicines/tamsulosin/'
  ]
};

RX_BODY['sildenafil'] = {
  what: {
    ar: 'السيلدينافيل دواء من فصيلة مثبّطات إنزيم PDE5، أشهر استعمالاته تحسين ضعف الانتصاب عند الرجال، وله شكل آخر باسم مختلف يعالج ارتفاع ضغط الشريان الرئوي. يُصرف بوصفة أقراصاً. لا يُحدث الانتصاب من تلقائه بل يهيّئ الجسم للاستجابة للإثارة الجنسية بزيادة تدفّق الدم إلى القضيب حين توجد رغبة، فبلا إثارة لا أثر له. وأخطر ما يُحفظ عنه علاقته القاتلة بأدوية النترات وموسّعات الشرايين التاجية، إذ يجتمع أثرهما على الأوعية فيهوي ضغط الدم هبوطاً خطيراً. ولهذا لا يُؤخذ إلا بعد أن يعرف الطبيب حالة القلب والأدوية المرافقة.',
    en: 'Sildenafil is a medicine of the PDE5 inhibitor family, best known for improving erectile dysfunction in men, with another form under a different name that treats high pressure in the lung artery. It is prescription-only as tablets. It does not produce an erection by itself but prepares the body to respond to sexual arousal by increasing blood flow to the penis when desire is present; without arousal it has no effect. The most important thing to remember about it is its deadly relationship with nitrate medicines and coronary vasodilators, since their effects on the vessels combine and blood pressure crashes dangerously. For this reason it is taken only after the doctor knows the state of the heart and the accompanying medicines.'
  },
  why: {
    ar: 'يوصف لضعف الانتصاب، أي العجز عن بلوغ انتصاب كافٍ للجماع أو الحفاظ عليه، أياً كان سببه عضوياً أو نفسياً في كثير من الحالات. وشكله الآخر المخصّص لارتفاع ضغط الشريان الرئوي يوسّع أوعية الرئة فيخفّف الحمل على القلب الأيمن ويحسّن قدرة المريض على المجهود. ولا يُستعمل لزيادة الرغبة الجنسية، فهو لا يخلق شهوة ولا يعالج سرعة القذف ولا العقم. ولا يُوصف للنساء لضعف الانتصاب لأنه لا معنى له عندهنّ. وينبغي أن يُفهم أنه دواء يعالج عرضاً، وقد يكون ضعف الانتصاب علامة على مرض قلب أو سكّري أو ضغط، فمراجعة الطبيب تكشف ما وراءه لا تكتفي بالحبّة.',
    en: 'It is prescribed for erectile dysfunction, the inability to reach or keep an erection sufficient for intercourse, whatever its cause, often organic or psychological. Its other form, meant for high pressure in the lung artery, widens the lung vessels so the load on the right heart eases and the person\'s capacity for exertion improves. It is not used to increase sexual desire, since it creates no libido and treats neither premature ejaculation nor infertility. It is not prescribed to women for erectile dysfunction, where it is meaningless. It should be understood as a medicine that treats a symptom, and erectile dysfunction may be a sign of heart disease, diabetes or high blood pressure, so seeing a doctor uncovers what lies behind it rather than settling for the tablet.'
  },
  how: {
    ar: 'حين تحدث الإثارة الجنسية يطلق الجسم إشارة كيميائية ترخي العضلة في أوعية القضيب فيندفع إليه الدم ويحدث الانتصاب، ثم يكسر إنزيم يُسمّى PDE5 هذه الإشارة فيزول الانتصاب. يعطّل السيلدينافيل هذا الإنزيم، فتبقى الإشارة أطول ويدوم اتّساع الأوعية وتدفّق الدم ما دامت الإثارة قائمة. ولأن الإشارة نفسها لا تُطلق إلا بالإثارة، فإن الدواء لا يعمل من دونها. والإنزيم ذاته موجود في أوعية الرئة، ولهذا يفيد شكله في ارتفاع ضغطها. وهذا الطريق يفسّر خطره مع النترات: النترات تطلق المادة نفسها في كل الجسم، فإذا مُنع كسرها تراكمت واتّسعت الأوعية في كل مكان وهوى الضغط.',
    en: 'When sexual arousal occurs the body releases a chemical signal that relaxes the muscle in the penile vessels, so blood rushes in and an erection forms; then an enzyme called PDE5 breaks this signal down and the erection subsides. Sildenafil disables this enzyme, so the signal lasts longer and the widening of the vessels and blood flow persist as long as arousal continues. Because the signal itself is only released by arousal, the drug does not work without it. The same enzyme is present in the lung vessels, which is why its form helps in raised lung pressure. This pathway explains its danger with nitrates: nitrates release the very same substance throughout the body, so if its breakdown is blocked it accumulates, vessels widen everywhere and blood pressure crashes.'
  },
  effects: {
    ar: 'أشيع آثاره صداع وتورّد في الوجه وإحساس بالحرارة واحتقان أو سيلان في الأنف وعسر هضم. وقد يسبّب دواراً وخفّة رأس، فيُنتبه للقيام المفاجئ. ومن آثاره المميّزة تغيّر مؤقّت في الرؤية: زيادة حساسية للضوء أو رؤية هالة زرقاء خفيفة أو تشوّش بسيط في تمييز الأزرق والأخضر، وهذا يزول غالباً من تلقائه. وقد يحدث ألم في الظهر أو العضلات. وهذه الآثار في مجملها عابرة ومحتمَلة، لكن بعض ما قد يظهر ليس عابراً البتّة، كفقد مفاجئ للبصر أو السمع أو انتصاب مؤلم يطول، وهذه مفصّلة في الحقل التالي لأنها تفرّق بين أثر يُحتمَل وطارئ يُهرَع فيه للمساعدة.',
    en: 'Its commonest effects are headache, flushing of the face, a sensation of warmth, nasal congestion or running and indigestion. It may cause dizziness and light-headedness, so care with sudden standing is sensible. A characteristic effect is a temporary change in vision: increased sensitivity to light, a faint blue haze, or slight difficulty telling blue from green, which usually settles by itself. Back or muscle pain may occur. On the whole these effects are transient and tolerable, but some of what may appear is not transient at all, such as a sudden loss of sight or hearing or a painful, prolonged erection, and these are set out in the next field because they separate an effect to be tolerated from an emergency in which help is urgent.'
  },
  warning: {
    ar: '⛔ لا تأخذه أبداً مع أيّ دواء نترات لألم الصدر (كالنيتروغليسرين وأقراص أو بخّاخ تحت اللسان والأيزوسوربايد) ولا مع مادّة الأميل نتريت، فالجمع قد يهوي بالضغط حتى الموت. واطلب الإسعاف فوراً عند ألم صدر أو ضيق نفس أثناء الجماع أو بعده، وعند إغماء، وعند انتصاب مؤلم يدوم طويلاً فهذا يخنق نسيج القضيب ويهدّده بأذى دائم إن تأخّر العلاج. وتوقّف وراجع فوراً عند فقد مفاجئ أو تغيّم في البصر في عين أو عينين، أو فقد سمع مفاجئ مع طنين ودوار، فقد ينذر بأذى دائم. واطلب الإسعاف عند علامات تحسّس شديد: تورّم الوجه والحلق وطفح متفقّع وضيق نفس. ولا تكرّر جرعة لأن الأولى لم تعمل قبل استشارة الطبيب.',
    en: 'Never take it with any nitrate medicine for chest pain (such as nitroglycerin, under-the-tongue tablets or spray, and isosorbide) or with amyl nitrite, because the combination can drop blood pressure to the point of death. Call an ambulance at once for chest pain or breathlessness during or after intercourse, for fainting, and for a painful erection that lasts a long time, which strangles the penile tissue and threatens it with permanent harm if treatment is delayed. Stop and seek review immediately for sudden loss or blurring of sight in one or both eyes, or sudden hearing loss with ringing and dizziness, which may herald lasting damage. Call an ambulance for signs of severe allergy: swelling of the face and throat, a blistering rash and breathlessness. Do not repeat a dose because the first did not work without asking the doctor.'
  },
  interact: {
    ar: 'أخطر تعارض على الإطلاق النترات وموسّعات الشرايين التاجية ومادّة الأميل نتريت، والجمع معها ممنوع لأنه قاتل. ويشتدّ خطر هبوط الضغط أيضاً مع حاصرات ألفا المستعملة للبروستاتا أو الضغط، ومع خافضات الضغط عموماً، فيباعد الطبيب بينها ويبدأ بحذر. وترفع بعض مضادات الفطريات ومضادات الفيروسات ومضاد حيوي كالكلاريثرومايسين مستوى السيلدينافيل لأنها تعطّل إنزيماً يكسره، فيزيد أثره وآثاره، وقد يخفّض الطبيب المقدار. وعصير الجريب فروت قد يرفع مستواه كذلك. والريفامبيسين يخفّضه. أخبر الطبيب بكل دواء للقلب أو الضغط تأخذه، فهذه المعلومة قد تنقذ حياة.',
    en: 'The gravest interaction of all is nitrates, coronary vasodilators and amyl nitrite, and combining with them is forbidden because it is deadly. The risk of a blood-pressure drop also increases with alpha-blockers used for the prostate or blood pressure, and with antihypertensives generally, so the doctor spaces them and starts cautiously. Some antifungals, antivirals and an antibiotic such as clarithromycin raise the level of sildenafil by blocking an enzyme that breaks it down, increasing its effect and side effects, and the doctor may lower the amount. Grapefruit juice may raise its level too. Rifampicin lowers it. Tell the doctor every heart or blood-pressure medicine you take, since this information may save a life.'
  },
  avoid: {
    ar: 'لا يأخذه من تحسّس منه، ولا من يأخذ النترات أو موسّعات الشرايين التاجية بأيّ شكل. ولا يُستعمل عند من نصحه الطبيب بتجنّب الجهد الجنسي لضعف قلبه، ولا عند من أصيب حديثاً بجلطة قلب أو سكتة أو هبوط ضغط شديد، ولا عند من فقد بصره سابقاً بسبب أذى في عصب العين مع هذه الفصيلة. ويُستعمل بحذر عند مرضى الكبد أو الكلى الشديد، ومن عنده تشوّه في القضيب أو مرض يهيّئ للانتصاب المطوّل كفقر الدم المنجلي، ومرضى القرحة النازفة. وهو دواء للرجال لا يُوصف للنساء ولا الأطفال لضعف الانتصاب. ومن عنده مرض قلب يستشير طبيبه قبله لأن الجماع نفسه مجهود على القلب.',
    en: 'It is not for anyone allergic to it, nor for anyone taking nitrates or coronary vasodilators in any form. It is not used in anyone advised by the doctor to avoid sexual exertion because of a weak heart, nor in anyone recently struck by a heart attack, stroke or severe low blood pressure, nor in anyone who previously lost sight from optic nerve damage with this family. It is used with caution in severe liver or kidney disease, in anyone with a deformity of the penis or a disease predisposing to prolonged erection such as sickle cell anaemia, and in people with a bleeding ulcer. It is a medicine for men, not prescribed to women or children for erectile dysfunction. Anyone with heart disease consults the doctor first, since intercourse itself is an exertion on the heart.'
  },
  updated: '2026-09-25',
  src: [
    'https://medlineplus.gov/druginfo/meds/a699015.html',
    'https://www.nhs.uk/medicines/sildenafil-viagra/'
  ]
};

RX_BODY['colchicine'] = {
  what: {
    ar: 'الكولشيسين دواء قديم مستخلص من نبات، يُصرف بوصفة أقراصاً، ويُستعمل في نوبة النقرس الحادّة وفي الوقاية من حمّى البحر المتوسط العائلية، وله دور في التهاب التامور المحيط بالقلب. ليس مسكّناً عاديّاً ولا مضاداً حيوياً، بل يكبح تجمّع خلايا الالتهاب التي تسبّب الألم والتورّم في النوبة. وأهمّ ما يُعرف عنه أن هامش أمانه ضيّق جداً: القدر الذي ينفع قريب من القدر الذي يسمّم، ولهذا يُلتزم فيه بما يحدّده الطبيب حرفياً، ولا يُزاد عليه أبداً ظنّاً أن الزيادة تسرّع الشفاء، فالزيادة عليه خطر جسيم قد يقتل.',
    en: 'Colchicine is an old plant-derived medicine, prescription-only as tablets, used in an acute gout attack, in the prevention of familial Mediterranean fever, and with a role in pericarditis around the heart. It is neither an ordinary painkiller nor an antibiotic, but it curbs the gathering of the inflammatory cells that cause the pain and swelling of an attack. The most important thing known about it is that its safety margin is very narrow: the amount that helps is close to the amount that poisons, so what the doctor sets is followed to the letter and never exceeded in the belief that more speeds recovery, since exceeding it is a grave danger that can kill.'
  },
  why: {
    ar: 'يوصف لنوبة النقرس الحادّة لتهدئة الألم والاحمرار والتورّم، وكلّما بُدئ مبكراً كان أنجع. ويُستعمل وقائيّاً في بداية علاج خفض حمض اليوريك، لأن بدء تلك الأدوية قد يثير نوبة، فيدرأ الكولشيسين ذلك مدّة. وهو حجر الأساس في حمّى البحر المتوسط العائلية، مرض وراثي يسبّب نوبات حمّى وألم بطن ومفاصل، إذ يقلّل تكرارها ويقي من مضاعفتها الخطيرة على الكلى. ويُستعمل في التهاب التامور وتكرّره مع علاج آخر. وهو لا يخفض حمض اليوريك في الدم بنفسه، فلا يغني عن دواء النقرس المزمن، ولا يعالج أنواع التهاب المفاصل الأخرى بلا قرار الطبيب.',
    en: 'It is prescribed for an acute gout attack to calm the pain, redness and swelling, and the earlier it is begun the more effective it is. It is used preventively at the start of urate-lowering treatment, because beginning those drugs may provoke an attack, and colchicine wards this off for a time. It is a cornerstone of familial Mediterranean fever, an inherited disease causing attacks of fever and abdominal and joint pain, reducing their frequency and guarding against its serious kidney complication. It is used in pericarditis and its recurrence alongside another treatment. It does not lower blood uric acid itself, so it does not replace a chronic gout drug, and it does not treat other kinds of arthritis without the doctor\'s decision.'
  },
  how: {
    ar: 'في النوبة تندفع خلايا الالتهاب، وخاصة نوع منها يُسمّى العَدِلات، إلى المفصل أو الغشاء المصاب فتُطلق مواد تُحدث الألم والحرارة والتورّم. تعتمد هذه الخلايا في حركتها وانقسامها على هيكل داخلي دقيق من أنابيب صغيرة يُبنى ويُفكّك باستمرار. يرتبط الكولشيسين بلبنة هذا الهيكل فيمنع بناءه، فتعجز خلايا الالتهاب عن الحركة والتجمّع وإطلاق موادّها، فتهدأ النوبة. وهذا الطريق نفسه يفسّر سمّيته حين يزيد: فالهيكل ذاته موجود في خلايا الأمعاء ونخاع العظم التي تنقسم بسرعة، فتتأذّى أولاً بالإسهال والقيء ثم بنقص خلايا الدم، ولهذا كان الفرق بين النافع والسامّ قريباً.',
    en: 'In an attack, inflammatory cells, especially a type called neutrophils, rush to the affected joint or membrane and release substances that cause pain, heat and swelling. These cells depend for their movement and division on a fine internal scaffold of tiny tubes that is continually built and taken apart. Colchicine binds the building block of this scaffold and prevents its construction, so the inflammatory cells cannot move, gather or release their substances, and the attack settles. This same pathway explains its toxicity when it is exceeded: the scaffold also exists in the rapidly dividing cells of the gut and bone marrow, which are harmed first by diarrhoea and vomiting and then by a fall in blood cells, which is why the line between helpful and toxic is close.'
  },
  effects: {
    ar: 'أشيع آثاره وأولها ظهوراً اضطراب الأمعاء: إسهال وغثيان وقيء ومغص. وهذه ليست مجرّد إزعاج، بل هي غالباً أوّل إشارة إلى أن الجسم بلغ حدّه من الدواء، فإذا ظهرت وجب التوقّف والرجوع إلى الطبيب لا مواصلة الأخذ. وقد يسبّب فقدان شهية وتعباً. ومع الاستعمال الطويل قد يظهر ضعف في العضلات أو خدر في الأطراف. والفارق بين هذا الدواء وغيره أن آثاره الهضمية إنذار مبكّر لا يُتجاهل، لأن تجاهله والاستمرار قد يقود إلى تسمّم خطير. ولهذا يُتعامل مع أيّ إسهال أو قيء يبدأ معه بجدّية، ويُنقل إلى الطبيب فوراً بدل احتماله.',
    en: 'Its commonest and earliest effect is gut upset: diarrhoea, nausea, vomiting and cramps. These are not mere nuisance; they are often the first sign that the body has reached its limit of the drug, and when they appear one should stop and return to the doctor rather than keep taking it. It may cause loss of appetite and tiredness. With long use, muscle weakness or numbness in the limbs may appear. What sets this drug apart is that its digestive effects are an early alarm not to be ignored, because ignoring them and continuing can lead to serious poisoning. So any diarrhoea or vomiting that begins with it is treated seriously and reported to the doctor at once rather than endured.'
  },
  warning: {
    ar: 'توقّف عن الدواء واتّصل بالطبيب في اليوم نفسه إذا بدأ إسهال أو قيء أو مغص، فهذه أوّل علامات بلوغ الحدّ، ومواصلة الأخذ عندها خطر. واطلب الإسعاف فوراً عند ضعف عضلي منتشر أو خدر وتنميل في الأطراف، وعند شحوب وتعب شديد أو حرارة أو التهاب حلق أو كدمات ونزف غير مفسّر، فقد تنذر بنقص خطير في خلايا الدم. واطلب الإسعاف عند علامات تحسّس شديد: تورّم الوجه والحلق وطفح متفقّع وضيق نفس. واحذر تماماً تكرار الجرعة لأن النوبة لم تهدأ، فالكولشيسين لا يُضاعف. وأيّ ابتلاع بالخطأ لكمّية أكبر، خاصة عند طفل، حالة طوارئ تستدعي المستشفى فوراً وإن بدا الشخص بخير.',
    en: 'Stop the medicine and telephone the doctor the same day if diarrhoea, vomiting or cramps begin, since these are the first signs of reaching the limit, and continuing then is dangerous. Call an ambulance at once for widespread muscle weakness or numbness and tingling in the limbs, and for pallor and severe tiredness, fever, sore throat, or unexplained bruising and bleeding, which may herald a dangerous fall in blood cells. Call an ambulance for signs of severe allergy: swelling of the face and throat, a blistering rash and breathlessness. Be absolutely wary of repeating the dose because the attack has not settled, for colchicine is not doubled. Any accidental swallowing of a larger amount, especially by a child, is an emergency needing hospital at once even if the person seems well.'
  },
  interact: {
    ar: 'تعارضاته كثيرة وخطرة بسبب ضيق هامشه. أخطرها الأدوية التي تعطّل إنزيماً وناقلاً يخرجانه من الجسم، فتراكمه إلى حدّ السمّ: مضاد حيوي كالكلاريثرومايسين والإريثرومايسين، ومضادات الفطريات، ومضادات الفيروسات، وبعض أدوية القلب كالفيراباميل والديلتيازيم، والسيكلوسبورين. وقد يمنع الطبيب الجمع أو يخفّض المقدار كثيراً. ويزيد خطر أذى العضلات حين يُجمع مع الستاتينات الخافضة للكوليسترول. وعصير الجريب فروت يرفع مستواه. ومرضى الكبد والكلى أشدّ عرضة لأنهم يطرحونه أبطأ. أخبر الصيدلي بكل ما تأخذه قبل أوّل قرص، فهذه ليست تعارضات هيّنة بل قد تكون مميتة.',
    en: 'Its interactions are many and dangerous because of its narrow margin. The gravest are drugs that block an enzyme and a transporter which remove it from the body, so it accumulates to a toxic level: an antibiotic such as clarithromycin and erythromycin, antifungals, antivirals, some heart drugs such as verapamil and diltiazem, and ciclosporin. The doctor may forbid the combination or greatly lower the amount. The risk of muscle harm rises when it is combined with cholesterol-lowering statins. Grapefruit juice raises its level. People with liver or kidney disease are more exposed because they clear it more slowly. Tell the pharmacist everything you take before the first tablet, since these are not trivial interactions but may be fatal.'
  },
  avoid: {
    ar: 'لا يأخذه من تحسّس منه. ويُمنع أو يُقلّل كثيراً عند اجتماع ضعف الكبد وضعف الكلى معاً، وعند مرضى الكلى الشديد، لأنه يتراكم فيسمّم. ويُستعمل بحذر شديد عند كبار السنّ، ومن عنده مرض في القلب أو الدم، ومن يأخذ الأدوية المتعارضة معه. وفي الحمل يُقدّر الطبيب فائدته وخطره، وقد يُستمرّ عليه في حمّى البحر المتوسط العائلية لأن إيقافه قد يضرّ أكثر، لكن القرار طبّي. وفي الرضاعة يُستعمل بحذر ومتابعة. ويجب أن يُحفظ بعيداً تماماً عن متناول الأطفال لأن كمّية صغيرة قد تقتل طفلاً. ولا يُشارَك مع أحد ولا يُعطى لغير من وُصف له.',
    en: 'It is not for anyone allergic to it. It is forbidden or greatly reduced when liver and kidney weakness coincide, and in severe kidney disease, because it accumulates and poisons. It is used with great caution in older people, in anyone with heart or blood disease, and in anyone taking the drugs that interact with it. In pregnancy the doctor weighs its benefit and risk, and it may be continued in familial Mediterranean fever because stopping it may harm more, but the decision is medical. In breastfeeding it is used with caution and monitoring. It must be kept entirely out of the reach of children, since a small amount can kill a child. It is not shared with anyone and not given to any but the person prescribed it.'
  },
  updated: '2026-09-25',
  src: [
    'https://medlineplus.gov/druginfo/meds/a682711.html',
    'https://www.nhs.uk/medicines/colchicine/'
  ]
};

RX_BODY['isotretinoin'] = {
  what: {
    ar: 'الإيزوتريتينوين مشتقّ قويّ من فيتامين أ، يُصرف بوصفة كبسولات، ويُستعمل لحبّ الشباب الشديد المتكتّل أو المقاوم للعلاجات الأخرى. هو أقوى ما يُعالَج به الحبّ، إذ يجفّف الغدد الدهنية ويصغّرها فيقطع أصل المشكلة، وكثيراً ما يحسم المرض في دورة واحدة. لكنه دواء بالغ الحذر لسببين: أنه يشوّه الأجنّة تشويهاً بالغاً إذا حملت المرأة أثناءه، ولذلك يُصرف تحت برنامج صارم لمنع الحمل، وأنه قد يؤثّر في المزاج والكبد والدهون، فيُتابَع بتحاليل. ولا يُبتاع من الإنترنت ولا يُؤخذ بلا إشراف طبيب مختصّ، لأن أذاه الخفيّ أخطر من أثره الظاهر.',
    en: 'Isotretinoin is a powerful vitamin A derivative, prescription-only as capsules, used for severe nodular acne or acne resistant to other treatments. It is the strongest treatment for acne, drying and shrinking the oil glands and so cutting the root of the problem, and it often settles the disease in a single course. But it is a medicine of the utmost caution for two reasons: it causes severe birth defects if a woman conceives while on it, so it is dispensed under a strict pregnancy-prevention programme, and it may affect mood, the liver and blood fats, so it is monitored with tests. It is not bought online or taken without a specialist doctor\'s supervision, because its hidden harm is graver than its visible effect.'
  },
  why: {
    ar: 'يوصف لحبّ الشباب الشديد الذي لم تنفع فيه المضادات الحيوية والعلاجات الموضعية، وخاصة النوع المتكتّل الكيسي الذي يترك ندوباً، والنوع الذي يعاود بشدّة أو يسبّب أذى نفسياً بالغاً. الغاية منه ليست تجميلاً عابراً بل إيقاف مرض جلدي يشوّه الوجه ويترك آثاراً دائمة إن أُهمل. ويُوصف أحياناً في أمراض جلدية أخرى شديدة بقرار طبيب مختصّ. وينبغي أن يُفهم أن أثره يبني على مدى أسابيع، وقد يشتدّ الحبّ في البداية قبل أن يتحسّن، وأن الهدف دورة علاجية محدّدة يقرّرها الطبيب لا استعمال دائم. ولا يُوصف لحبّ خفيف أو متوسّط تكفيه علاجات أخفّ وأأمن.',
    en: 'It is prescribed for severe acne unhelped by antibiotics and topical treatments, especially the cystic, nodular kind that leaves scars, and the kind that recurs severely or causes serious psychological harm. Its aim is not passing cosmetics but stopping a skin disease that disfigures the face and leaves permanent marks if neglected. It is sometimes prescribed for other severe skin diseases by a specialist\'s decision. It should be understood that its effect builds over weeks, and the acne may worsen at first before it improves, and that the goal is a defined course the doctor decides, not permanent use. It is not prescribed for mild or moderate acne for which gentler, safer treatments suffice.'
  },
  how: {
    ar: 'حبّ الشباب مشكلته أربعة عوامل: غدد دهنية نشطة تفرز زيتاً كثيراً، ومسامّ تنسدّ بالخلايا الميتة، وجرثومة تنمو في الزيت المحتبس، والتهاب يتبع ذلك. يعمل الإيزوتريتينوين على أصل السلسلة: يصغّر الغدد الدهنية جذريّاً ويقلّل إفرازها، فيجفّ الوسط الذي تعيش فيه الجرثومة وتقلّ المسامّ المسدودة ويهدأ الالتهاب. وهو الوحيد بين علاجات الحبّ الذي يمسّ العوامل الأربعة معاً، ولهذا كان أقواها. لكن هذا التجفيف نفسه يفسّر آثاره: جفاف الشفتين والجلد والعين والأنف، ولأنه مشتقّ فيتامين أ يتراكم أثره فيؤذي الجنين، ولذلك كان منع الحمل شرطاً لا خياراً.',
    en: 'Acne stems from four factors: active oil glands secreting much oil, pores blocked with dead cells, a bacterium growing in the trapped oil, and the inflammation that follows. Isotretinoin acts on the root of the chain: it radically shrinks the oil glands and reduces their secretion, so the medium the bacterium lives in dries, blocked pores lessen and the inflammation calms. It is the only acne treatment that touches all four factors together, which is why it is the strongest. But this very drying explains its effects: dryness of the lips, skin, eyes and nose, and because it is a vitamin A derivative its effect accumulates and harms the fetus, which is why pregnancy prevention is a condition, not a choice.'
  },
  effects: {
    ar: 'أشيع آثاره الجفاف: شفاه متشقّقة، وجلد جافّ متقشّر، وجفاف في العين يزعج لابس العدسات، وجفاف الأنف مع رعاف خفيف. وتزيد حساسية الجلد للشمس فيلزم الوقاية. وقد يسبّب ألماً في العضلات والمفاصل خاصة مع الرياضة، وصداعاً، وتعباً. وقد يشتدّ الحبّ في الأسابيع الأولى قبل أن يتحسّن. وترتفع أحياناً دهون الدم وإنزيمات الكبد فتُتابَع بتحاليل دورية. وهذه الآثار المتوقّعة تُدار بالمرطّبات وقطرات العين وواقي الشمس. لكن ما يخصّ المزاج والرؤية الليلية والبطن ليس من هذا الباب، بل من باب ما يُوقف له الدواء ويُراجَع الطبيب، وهو مفصّل في الحقل التالي.',
    en: 'Its commonest effects are dryness: cracked lips, dry flaking skin, dry eyes that trouble contact-lens wearers, and a dry nose with mild nosebleeds. Skin sensitivity to the sun increases so protection is needed. It may cause muscle and joint pain, especially with exercise, headache and tiredness. The acne may worsen in the first weeks before it improves. Blood fats and liver enzymes sometimes rise, so they are followed with periodic tests. These expected effects are managed with moisturisers, eye drops and sunscreen. But what concerns mood, night vision and the abdomen is not of this kind but of the kind for which the drug is stopped and the doctor seen, set out in the next field.'
  },
  warning: {
    ar: '⛔ لا يُؤخذ في الحمل مطلقاً، وأيّ حمل يحدث أثناءه أو بعده بمدّة يحدّدها الطبيب حالة طوارئ تستدعي مراجعة فورية لأنه يشوّه الجنين. توقّف وراجع فوراً عند تبدّل المزاج أو اكتئاب أو انطواء أو تهيّج، وخاصة أيّ فكرة إيذاء نفس، فهذه لا تنتظر. واطلب الإسعاف عند ألم بطن شديد أو إسهال مدمّى أو قيء مستمرّ، وعند صداع شديد مع غثيان وتغيّم رؤية قد ينذر بارتفاع الضغط داخل الجمجمة، وعند اصفرار العين والجلد. وراجع فوراً عند ضعف مفاجئ في الرؤية الليلية، وعند طفح متقشّر أو متفقّع في الجلد أو الفم، وعند ألم عضلي شديد مع بول داكن. ولا تتبرّع بالدم أثناءه وبعده مدّة يحدّدها الطبيب.',
    en: 'It is never taken in pregnancy, and any pregnancy occurring during it or for a period the doctor sets afterwards is an emergency needing immediate review, because it deforms the fetus. Stop and seek review at once for a change of mood, depression, withdrawal or agitation, and above all any thought of self-harm, which does not wait. Call an ambulance for severe abdominal pain, bloody diarrhoea or persistent vomiting, for a severe headache with nausea and blurred vision that may herald raised pressure inside the skull, and for yellowing of the eyes and skin. Seek review at once for a sudden decline in night vision, for a peeling or blistering rash of the skin or mouth, and for severe muscle pain with dark urine. Do not donate blood during it and for a period the doctor sets afterwards.'
  },
  interact: {
    ar: 'لا يُجمع أبداً مع فيتامين أ أو مكمّلاته لأن أثرهما يتراكم فيزيد السمّية. ولا يُجمع مع مضاد حيوي من التتراسيكلينات كالدوكسيسيكلين، لأن كليهما قد يرفع الضغط داخل الجمجمة. ويُنتبه للأدوية المؤثّرة في الكبد والدهون. وتقشير البشرة أو إزالة الشعر بالشمع أو الليزر أثناءه وبعده بمدّة قد يجرح الجلد الرقيق ويترك ندوباً، فتؤجَّل. ويزيد أثر الكحول على الكبد والدهون فيُقلّل. وحبوب منع الحمل تُستعمل ضمن برنامج المنع لكنّ حبّة البروجستيرون وحدها قد لا تكفي، فيُختار طريقتان معاً بإشراف الطبيب. أخبري الطبيب بكل دواء ومكمّل، فبعض المكمّلات الشعبية للبشرة تحتوي فيتامين أ خفيّاً.',
    en: 'It is never combined with vitamin A or its supplements, because their effects accumulate and increase toxicity. It is not combined with a tetracycline antibiotic such as doxycycline, because both may raise pressure inside the skull. Care is needed with drugs affecting the liver and blood fats. Skin peeling, or hair removal by wax or laser during it and for a period afterwards, may wound the thinned skin and leave scars, so they are postponed. Its effect on the liver and fats is worsened by alcohol, so alcohol is reduced. Contraceptive pills are used within the prevention programme, but the progesterone-only pill alone may not suffice, so two methods together are chosen under the doctor\'s supervision. Tell the doctor every drug and supplement, since some folk skin supplements hide vitamin A.'
  },
  avoid: {
    ar: '⛔ لا تأخذه المرأة الحامل ولا من قد تحمل إلا داخل برنامج صارم لمنع الحمل بطريقتين مؤكّدتين واختبارات حمل منتظمة قبله وأثناءه وبعده. ولا يأخذه من تحسّس منه أو من فيتامين أ. ويُمنع أو يُراقب بشدّة عند مرضى الكبد، ومن عنده دهون دم مرتفعة جداً، ومرضى السكّري، ومن له تاريخ اكتئاب أو مرض نفسي فيُتابَع مزاجه عن قرب. ولا يُعطى مع التتراسيكلينات. ولا يُنصح به في الرضاعة. ويُحفظ بعيداً عن الآخرين ولا يُعطى لأحد سواه أبداً، ولا سيّما امرأة في سنّ الإنجاب. والغاية أن يبقى قراره وصرفه ومتابعته بيد طبيب جلد مختصّ لا غير.',
    en: 'A pregnant woman, or any woman who might conceive, does not take it except within a strict pregnancy-prevention programme with two reliable methods and regular pregnancy tests before, during and after. It is not for anyone allergic to it or to vitamin A. It is forbidden or strictly monitored in people with liver disease, very high blood fats, diabetes, and a history of depression or mental illness, whose mood is watched closely. It is not given with tetracyclines. It is not advised in breastfeeding. It is kept away from others and never given to anyone else, least of all a woman of childbearing age. The aim is that its decision, dispensing and monitoring stay in the hands of a specialist skin doctor alone.'
  },
  updated: '2026-09-25',
  src: [
    'https://medlineplus.gov/druginfo/meds/a681043.html',
    'https://www.nhs.uk/medicines/isotretinoin-capsules/'
  ]
};

RX_BODY['sitagliptin'] = {
  what: {
    ar: 'السيتاغليبتين دواء لسكّري النوع الثاني يُصرف بوصفة أقراصاً، وينتمي إلى فصيلة مثبّطات DPP-4 التي تُعرف أيضاً بالغليبتينات. يعمل برفع هرمونات طبيعية تفرزها الأمعاء بعد الأكل تُسمّى الإنكريتين، وهذه الهرمونات تنبّه البنكرياس لإفراز الأنسولين حين يرتفع السكّر وتكبح هرموناً يرفعه. لأنه يعمل مع الأكل فحسب فهو لطيف نسبياً ونادراً ما يخفض السكّر إلى حدّ خطير وحده، ولا يزيد الوزن غالباً. يُؤخذ حبّة تُبتلع، ويُجمع كثيراً مع الميتفورمين في قرص واحد. وهو غالباً خطوة تُضاف حين لا يكفي الميتفورمين وحده لضبط السكّر.',
    en: 'Sitagliptin is a tablet for type 2 diabetes, prescription-only, of the DPP-4 inhibitor family also known as gliptins. It works by raising natural hormones the gut releases after eating called incretins; these hormones prompt the pancreas to release insulin when sugar rises and suppress a hormone that raises it. Because it works only with eating, it is relatively gentle and rarely lowers sugar to a dangerous level on its own, and it usually does not add weight. It is taken as a swallowed tablet and is often combined with metformin in a single tablet. It is usually a step added when metformin alone is not enough to control blood sugar.'
  },
  why: {
    ar: 'يوصف لسكّري النوع الثاني إلى جانب الحمية والرياضة، غالباً حين لا يكفي الميتفورمين وحده لضبط السكّر، فيُضاف إليه أو يُجمع في قرص واحد. وقد يُستعمل مع أدوية سكّر أخرى أو مع الأنسولين بقرار الطبيب. يميل الأطباء إليه عند من يخشى عنده نقص السكّر أو زيادة الوزن، لأنه لطيف في هذين، فيناسب كبار السنّ ومن يصعب عليه ضبط مواعيد الأكل. وهو لا يعالج سكّري النوع الأول ولا الحالة الحادّة المسمّاة الحماض الكيتوني، ولا يُغني عن الحمية وتنظيم الحياة. والغاية منه خفض السكّر التراكمي على المدى لتقليل مضاعفات السكّري في العين والكلى والأعصاب، لا مجرّد رقم يومي.',
    en: 'It is prescribed for type 2 diabetes alongside diet and exercise, usually when metformin alone is not enough to control sugar, so it is added to it or combined in a single tablet. It may be used with other sugar drugs or with insulin by the doctor\'s decision. Doctors favour it when low sugar or weight gain is feared, because it is gentle on both, so it suits older people and those who struggle to keep meal times. It does not treat type 1 diabetes or the acute state called ketoacidosis, and it does not replace diet and an ordered life. Its aim is lowering the long-term average sugar to reduce the diabetes complications in the eyes, kidneys and nerves, not merely a daily number.'
  },
  how: {
    ar: 'حين نأكل تفرز الأمعاء هرمونات الإنكريتين، وأشهرها واحد يُنبّه البنكرياس لإفراز الأنسولين بقدر ما ارتفع السكّر، ويكبح في الوقت نفسه هرموناً معاكساً يرفعه من الكبد. لكن هذه الهرمونات تُكسر بسرعة بإنزيم يُسمّى DPP-4 فيقصر أثرها. يعطّل السيتاغليبتين هذا الإنزيم، فتبقى هرمونات الإنكريتين أطول ويقوى أثرها بعد الأكل: أنسولين أكثر حين يلزم، وهرمون رافع للسكّر أقلّ. ولأن هذا كلّه مرتبط بارتفاع السكّر بعد الوجبة، فإن الدواء لا يدفع السكّر إلى الهبوط الخطير حين يكون طبيعياً، وهذا سرّ لطفه مقارنة بأدوية تعصر البنكرياس عصراً دائماً.',
    en: 'When we eat, the gut releases incretin hormones, the best known of which prompts the pancreas to release insulin in proportion to the rise in sugar, and at the same time suppresses an opposing hormone that raises it from the liver. But these hormones are quickly broken down by an enzyme called DPP-4, so their effect is brief. Sitagliptin disables this enzyme, so the incretin hormones last longer and their effect after eating strengthens: more insulin when needed, less sugar-raising hormone. Because all of this is tied to the after-meal rise in sugar, the drug does not push sugar to a dangerous low when it is normal, and there lies the secret of its gentleness compared with drugs that squeeze the pancreas continually.'
  },
  effects: {
    ar: 'يتحمّله أكثر الناس جيّداً، وأشيع ما يُذكر معه أعراض شبيهة بالزكام: سيلان أو احتقان الأنف والتهاب الحلق، وصداع. وقد يسبّب اضطراباً خفيفاً في المعدة أو إمساكاً. ونقص السكّر قليل معه وحده، لكنه يزيد إذا جُمع مع الأنسولين أو أدوية السلفونيل يوريا، فيُعرف صاحبه علامات النقص من رجفة وتعرّق وجوع وتشوّش. وهذه الآثار في مجملها خفيفة، لكن هناك آثاراً أندر لكنها أهمّ لا تُهمَل: ألم مفاصل قد يشتدّ، وألم بطن قد ينذر بالتهاب البنكرياس، وطفح تحسّسي. والفارق بين المحتمَل وما يستدعي التوقّف مذكور في الحقل التالي.',
    en: 'Most people tolerate it well, and the commonest thing reported with it is cold-like symptoms: a runny or blocked nose and sore throat, and headache. It may cause mild stomach upset or constipation. Low sugar is uncommon with it alone, but it increases if combined with insulin or sulfonylurea drugs, so the person is taught the signs of a low: shakiness, sweating, hunger and confusion. On the whole these effects are mild, but there are rarer yet more important effects not to be ignored: joint pain that may become severe, abdominal pain that may herald pancreatitis, and an allergic rash. The difference between the tolerable and what demands stopping is in the next field.'
  },
  warning: {
    ar: 'توقّف عن الدواء واطلب الإسعاف عند ألم شديد ومستمرّ في أعلى البطن ينفذ إلى الظهر مع غثيان وقيء، فقد يكون التهاب بنكرياس. واطلب الإسعاف عند علامات تحسّس شديد: تورّم الوجه أو الشفتين أو اللسان أو الحلق، وضيق نفس، وطفح متورّم أو متقشّر أو متفقّع. وراجع فوراً عند ألم مفاصل شديد يعطّل الحركة، وعند علامات فشل قلب كضيق نفس متزايد وتورّم الساقين وزيادة وزن سريعة، فبعض هذه الفصيلة رُبط به عند مرضى معيّنين. وتعلّم علامات نقص السكّر إن كنت تجمعه مع الأنسولين أو السلفونيل يوريا، وعالج النقص فوراً بسكّر سريع ثم راجع الطبيب في تعديل الخطّة.',
    en: 'Stop the medicine and call an ambulance for severe, persistent pain in the upper abdomen boring through to the back with nausea and vomiting, which may be pancreatitis. Call an ambulance for signs of severe allergy: swelling of the face, lips, tongue or throat, breathlessness, and a swollen, peeling or blistering rash. Seek review at once for severe joint pain that disables movement, and for signs of heart failure such as worsening breathlessness, swelling of the legs and rapid weight gain, since some of this family has been linked to it in certain patients. Learn the signs of low sugar if you combine it with insulin or a sulfonylurea, treat a low at once with fast sugar, then see the doctor about adjusting the plan.'
  },
  interact: {
    ar: 'تعارضاته أقلّ من كثير من أدوية السكّر. أهمّها أنه يزيد خطر نقص السكّر حين يُجمع مع الأنسولين أو أدوية السلفونيل يوريا، فقد يخفّض الطبيب مقدارهما عند إضافته. ويُنتبه له مع الديجوكسين إذ قد يرفع مستواه قليلاً فيُتابَع. ومرضى الكلى قد يحتاجون تعديل المقدار لأن الكلى تطرحه، فمتابعة وظيفة الكلى جزء من علاجه. وعموماً يُخبَر كل طبيب وصيدلي بأنه دواء سكّر حتى تُوازن الخطّة، ولا يُوقف فجأة بلا مشورة لأن السكّر قد يرتفع. أخبر الطبيب بأيّ دواء جديد، ولا تضف مكمّلات تدّعي خفض السكّر دون علمه لئلّا يجتمع أثرها فيهبط السكّر.',
    en: 'Its interactions are fewer than many diabetes drugs. The chief one is that it raises the risk of low sugar when combined with insulin or sulfonylurea drugs, so the doctor may lower their amount when adding it. Care is taken with digoxin, since it may slightly raise its level, which is monitored. People with kidney disease may need the amount adjusted because the kidneys clear it, so following kidney function is part of its treatment. In general every doctor and pharmacist is told it is a diabetes drug so the plan is balanced, and it is not stopped suddenly without advice since sugar may rise. Tell the doctor of any new drug, and do not add supplements claiming to lower sugar without their knowledge, lest their effects combine and sugar fall.'
  },
  avoid: {
    ar: 'لا يأخذه من تحسّس منه، ولا من أُصيب بالتهاب بنكرياس بسببه من قبل، ويُستعمل بحذر عند من له تاريخ التهاب بنكرياس أو حصى مرارة. وهو ليس لسكّري النوع الأول ولا للحماض الكيتوني السكّري، وهما يحتاجان الأنسولين. ويحتاج مرضى الكلى الشديد تعديل المقدار ومتابعة، ومرضى فشل القلب متابعة خاصة. وفي الحمل لا يُفضّل عادة ويُتحوّل غالباً إلى الأنسولين الأضبط والأأمن للجنين بقرار الطبيب، وكذلك في الرضاعة يُقدّر البديل. ولا يُوقف من تلقاء المريض عند مرض عابر بل يستشير طبيبه، لأن ضبط السكّر أثناء المرض قد يتغيّر. وهو جزء من خطّة تشمل الحمية والحركة والمتابعة الدورية.',
    en: 'It is not for anyone allergic to it, nor for anyone in whom it previously caused pancreatitis, and it is used with caution in anyone with a history of pancreatitis or gallstones. It is not for type 1 diabetes or diabetic ketoacidosis, which need insulin. People with severe kidney disease need the amount adjusted and monitoring, and people with heart failure need special follow-up. In pregnancy it is usually not preferred and is often switched to insulin, which is tighter and safer for the fetus, by the doctor\'s decision, and in breastfeeding an alternative is weighed. The patient does not stop it alone during a passing illness but consults the doctor, since sugar control during illness may change. It is part of a plan that includes diet, activity and regular follow-up.'
  },
  updated: '2026-09-25',
  src: [
    'https://medlineplus.gov/druginfo/meds/a606023.html',
    'https://www.nhs.uk/medicines/sitagliptin/'
  ]
};

RX_BODY['alendronate'] = {
  what: {
    ar: 'الأليندرونات دواء لهشاشة العظام من فصيلة البيسفوسفونات، يُصرف بوصفة أقراصاً. العظم نسيج حيّ يُهدَم ويُبنى باستمرار، وفي الهشاشة يغلب الهدم على البناء فيرقّ العظم ويسهل كسره. يبطّئ الأليندرونات الخلايا الهادمة للعظم فيميل الميزان إلى البناء، فتزيد كثافة العظم تدريجياً ويقلّ خطر الكسر خاصة في الورك والعمود الفقري. أهمّ ما يميّزه طريقة أخذه الصارمة: يُبتلع على معدة فارغة أوّل النهار بماء عادي وحده، ثم يبقى المريض منتصباً ولا يستلقي ولا يأكل ولا يشرب حتى المدّة التي حدّدها الطبيب، وإلا هيّج المريء وقرّحه. وهو علاج طويل يُتابَع دوريّاً.',
    en: 'Alendronate is a medicine for osteoporosis of the bisphosphonate family, prescription-only as tablets. Bone is a living tissue continually broken down and built up, and in osteoporosis breakdown outweighs building, so the bone thins and breaks easily. Alendronate slows the bone-breaking cells so the balance tips towards building, and bone density gradually rises and the risk of fracture, especially of the hip and spine, falls. What most sets it apart is the strict way it is taken: swallowed on an empty stomach at the start of the day with plain water alone, then the person stays upright and does not lie down, eat or drink until the period the doctor set, or it irritates and ulcerates the gullet. It is a long treatment followed periodically.'
  },
  why: {
    ar: 'يوصف لعلاج هشاشة العظام والوقاية منها، وأشهر من يأخذه النساء بعد سنّ اليأس لأن نقص الهرمون يسرّع فقد العظم. ويُستعمل عند الرجال المصابين بالهشاشة، وعند من يأخذ الكورتيزون مدداً طويلة لأنه يضعف العظم. ويُستعمل في مرض باجيت العظمي حيث يُبنى العظم مشوّهاً. الغاية منه ليست شعوراً يوميّاً، فالهشاشة صامتة لا تُحسّ حتى يقع الكسر، بل هي تقليل احتمال كسر مؤلم قد يقعد صاحبه، خاصة كسر الورك عند كبار السنّ. ولا يعالج ألم المفاصل ولا هشاشة سببها نقص فيتامين د وحده دون تصحيح النقص، فكثيراً ما يُعطى معه الكالسيوم وفيتامين د لأن الدواء يبني على أساس متين.',
    en: 'It is prescribed to treat and prevent osteoporosis, and the best-known people who take it are women after menopause, because the hormone drop speeds bone loss. It is used in men with osteoporosis, and in anyone taking corticosteroids for long periods because they weaken bone. It is used in Paget\'s bone disease, where bone is built deformed. Its aim is not a daily feeling, for osteoporosis is silent and unfelt until a fracture occurs, but reducing the chance of a painful fracture that may lay its owner low, especially a hip fracture in older people. It does not treat joint pain, nor osteoporosis caused by vitamin D deficiency alone without correcting the deficiency, so calcium and vitamin D are often given with it, since the drug builds on a firm foundation.'
  },
  how: {
    ar: 'يُبنى العظم ويُهدَم بخليتين متقابلتين: خلية تبني وخلية تهدم. في الهشاشة تنشط الخلايا الهادمة فتأكل العظم أسرع مما يُبنى. يلتصق الأليندرونات بسطح العظم في المواضع التي يجري فيها الهدم، وحين تبتلعه الخلية الهادمة يعطّل عملها ويقصّر عمرها، فيبطؤ الهدم ويلحق به البناء فترجح كفّته. النتيجة عظم أكثف وأقوى وأقلّ عرضة للكسر مع الوقت. ولأن الدواء يمتصّ بصعوبة من الأمعاء وينجذب إلى العظم، وجب أخذه على معدة فارغة تماماً بماء وحده، فأي طعام أو حليب أو قهوة أو حتى ماء معدني يمنع امتصاله فيضيع أثره، وبقاء المريض منتصباً يحمي المريء من تهيّجه.',
    en: 'Bone is built and broken by two opposing cells: one that builds and one that breaks down. In osteoporosis the breaking cells become active and eat bone faster than it is built. Alendronate attaches to the bone surface at the sites where breakdown is happening, and when the breaking cell swallows it, it disables its work and shortens its life, so breakdown slows and building catches up and its side prevails. The result is denser, stronger bone less prone to fracture over time. Because the drug is poorly absorbed from the gut and drawn to bone, it must be taken on a completely empty stomach with water alone; any food, milk, coffee or even mineral water prevents its absorption and its effect is lost, and staying upright protects the gullet from its irritation.'
  },
  effects: {
    ar: 'أشيع آثاره تتعلّق بالمريء والمعدة: حرقة، وعسر هضم، وألم أو صعوبة عند البلع، وغثيان، وانتفاخ. وتقلّ كثيراً إذا التزم المريض طريقة الأخذ الصحيحة على معدة فارغة مع البقاء منتصباً. وقد يسبّب ألماً في العضلات أو المفاصل أو العظام، وصداعاً. ومن آثاره المعروفة عند بدئه شعور شبيه بالزكام مع أوجاع عضلية يزول من تلقائه. وهذه الآثار في مجملها محتمَلة ومرتبطة بطريقة الأخذ. لكن هناك آثاراً نادرة لكنها مهمّة تخصّ الفكّ والفخذ والمريء لا تُهمَل، وهي مفصّلة في الحقل التالي، لأن الفارق بين إزعاج عابر وعلامة تستدعي الطبيب يجب أن يكون واضحاً.',
    en: 'Its commonest effects concern the gullet and stomach: heartburn, indigestion, pain or difficulty on swallowing, nausea and bloating. They lessen greatly if the person keeps to the correct way of taking it on an empty stomach and staying upright. It may cause pain in the muscles, joints or bones, and headache. A known effect at its start is a cold-like feeling with muscle aches that settles by itself. On the whole these effects are tolerable and tied to the way it is taken. But there are rare yet important effects concerning the jaw, the thigh and the gullet that are not ignored, set out in the next field, because the difference between a passing nuisance and a sign needing the doctor must be clear.'
  },
  warning: {
    ar: 'توقّف عن الدواء وراجع الطبيب عند ألم أو صعوبة عند البلع، أو ألم خلف عظمة الصدر، أو حرقة جديدة أو متفاقمة، فقد تكون قرحة في المريء. واذهب لطبيب الأسنان عند ألم أو تورّم أو تنميل في الفكّ أو خروج قيح أو تخلخل سنّ، فهذا قد ينذر بأذى نادر في عظم الفكّ، وأخبر أيّ طبيب أسنان أنك تأخذه قبل خلع أو زرع. وراجع فوراً عند ألم جديد في الفخذ أو أعلى الساق أو الأربية يشتدّ مع المشي، فقد يسبق كسراً غير معتاد في عظم الفخذ. واطلب الإسعاف عند علامات تحسّس شديد: تورّم الوجه والحلق وطفح متفقّع وضيق نفس، وعند ألم عين شديد أو احمرارها مع تغيّم الرؤية.',
    en: 'Stop the medicine and see the doctor for pain or difficulty on swallowing, pain behind the breastbone, or new or worsening heartburn, which may be an ulcer in the gullet. Go to the dentist for pain, swelling or numbness in the jaw, discharge of pus or a loosening tooth, which may herald rare harm to the jawbone, and tell any dentist you take it before an extraction or implant. Seek review at once for new pain in the thigh, upper leg or groin that worsens with walking, which may precede an unusual thighbone fracture. Call an ambulance for signs of severe allergy: swelling of the face and throat, a blistering rash and breathlessness, and for severe eye pain or redness with blurred vision.'
  },
  interact: {
    ar: 'أهمّ ما يُحفظ أن كل ما يُبتلع مع الأليندرونات تقريباً يمنع امتصاله: الطعام والحليب ومشتقّاته، والقهوة والشاي وعصير الفواكه، وأقراص الكالسيوم والحديد والمغنيسيوم ومضادات الحموضة، وحتى الماء المعدني. لذلك يُؤخذ على معدة فارغة بماء عادي وحده، ويؤجَّل كل ما سبق إلى ما بعد المدّة التي حدّدها الطبيب. ومضادات الالتهاب غير الستيرويدية كالإيبوبروفين تزيد خطر تهيّج المعدة والمريء إذا جُمعت معه، فيُنتبه لذلك. وقد يحتاج مريض الكلى تقديراً خاصاً. أخبر الصيدلي بكل ما تأخذه، وخصّ بالذكر مكمّلات الكالسيوم وفيتامين د لأنها تُؤخذ في وقت مختلف لا معه.',
    en: 'The most important thing to remember is that almost everything swallowed with alendronate prevents its absorption: food, milk and its products, coffee, tea and fruit juice, calcium, iron and magnesium tablets, antacids, and even mineral water. So it is taken on an empty stomach with plain water alone, and all of the above is deferred until after the period the doctor set. Non-steroidal anti-inflammatories such as ibuprofen increase the risk of stomach and gullet irritation if combined with it, so care is taken. A person with kidney disease may need a special judgement. Tell the pharmacist everything you take, and mention calcium and vitamin D supplements in particular, because they are taken at a different time, not with it.'
  },
  avoid: {
    ar: 'لا يأخذه من تحسّس منه، ولا من لا يستطيع الجلوس أو الوقوف منتصباً المدّة اللازمة بعده، لأن استلقاءه يهدّد مريئه. ويُمنع عند من عنده مشكلات في المريء تؤخّر مرور الطعام كالتضيّق أو الارتخاء، وعند من ينخفض عنده الكالسيوم في الدم حتى يُصحَّح أولاً. ويُستعمل بحذر عند من له قرحة أو التهاب نشط في المعدة أو المريء، وعند مرضى الكلى الشديد. وقبل البدء يُصحَّح نقص فيتامين د والكالسيوم وتُعالَج مشكلات الأسنان قدر الإمكان. وفي الحمل والرضاعة لا يُستعمل عادة لأن أثره يبقى في العظم طويلاً، والقرار للطبيب. ويحتاج كبار السنّ عناية بطريقة الأخذ حتى لا يتأذّى المريء.',
    en: 'It is not for anyone allergic to it, nor for anyone who cannot sit or stand upright for the needed period after it, because lying down threatens the gullet. It is forbidden in anyone with gullet problems that delay the passage of food, such as narrowing or slackness, and in anyone whose blood calcium is low until it is corrected first. It is used with caution in anyone with an active ulcer or inflammation of the stomach or gullet, and in people with severe kidney disease. Before starting, vitamin D and calcium deficiency are corrected and dental problems treated as far as possible. In pregnancy and breastfeeding it is usually not used, because its effect lingers long in bone, and the decision is the doctor\'s. Older people need care with the way it is taken so the gullet is not harmed.'
  },
  updated: '2026-09-25',
  src: [
    'https://medlineplus.gov/druginfo/meds/a601011.html',
    'https://www.nhs.uk/medicines/alendronic-acid/'
  ]
};

RX_BODY['famotidine'] = {
  what: {
    ar: 'الفاموتيدين دواء يقلّل حمض المعدة، من فصيلة حاصرات مستقبل H2. صار من أشهر أدوية الحموضة بعد أن سُحب الرانيتيدين من الأسواق لشبهة تلوّث ببعض دفعاته، فحلّ الفاموتيدين محلّه كبديل آمن معروف. يُصرف كثير من أشكاله بلا وصفة لعلاج الحرقة وعسر الهضم العارض، وأشكال أقوى بوصفة للقرحة والارتجاع. يعمل بتخفيف إفراز الحمض لا بتعديله بعد إفرازه، فأثره أبطأ ظهوراً من مضادات الحموضة السريعة لكنه أطول، وأخفّ وأقصر من مثبّطات مضخّة البروتون. وهو خيار جيّد للحالات الخفيفة والمتوسّطة ولمن يريد راحة مسائية تدوم ساعات.',
    en: 'Famotidine is a medicine that reduces stomach acid, of the H2 receptor blocker family. It became one of the best-known acid medicines after ranitidine was withdrawn from the market over a suspected contamination in some of its batches, and famotidine took its place as a known safe alternative. Many of its forms are available without prescription for heartburn and occasional indigestion, and stronger forms by prescription for ulcer and reflux. It works by reducing acid secretion rather than neutralising it after secretion, so its effect is slower to appear than fast antacids but longer, and gentler and shorter than proton-pump inhibitors. It is a good choice for mild and moderate cases and for anyone wanting evening relief that lasts hours.'
  },
  why: {
    ar: 'يوصف للحرقة وعسر الهضم الحمضي والارتجاع المريئي، ولقرحة المعدة والاثني عشر لتخفيف الحمض حتى تلتئم، ولالتهاب المعدة المزمن حين يزيد الحمض الأعراض. ويُستعمل للوقاية من حرقة تثيرها أطعمة معيّنة إذا أُخذ قبلها. وله دور في حالات فرط إفراز الحمض الشديدة كمتلازمة نادرة تُفرز الحمض بغزارة. يميل إليه الناس للراحة العارضة والمسائية لأنه يُصرف بلا وصفة ويكفي في الحالات الخفيفة. لكن الحرقة المتكرّرة أو المستمرّة تحتاج تشخيصاً لا مجرّد كتمها، لأنها قد تخفي مرضاً يستدعي علاجاً آخر، فإن طالت الأعراض أو لم تستجب وجبت مراجعة الطبيب بدل إطالة الدواء وحده.',
    en: 'It is prescribed for heartburn, acid indigestion and reflux, for stomach and duodenal ulcer to reduce acid until they heal, and for chronic gastritis when acid worsens the symptoms. It is used to prevent heartburn provoked by certain foods if taken beforehand. It has a role in severe acid-oversecretion states such as a rare syndrome that pours out acid. People turn to it for occasional and evening relief because it is available without prescription and suffices in mild cases. But recurrent or persistent heartburn needs a diagnosis, not merely silencing, because it may hide a disease needing another treatment, so if symptoms last or do not respond, seeing the doctor is due rather than prolonging the drug alone.'
  },
  how: {
    ar: 'تُفرز خلايا في جدار المعدة الحمض، وتُنبَّه لذلك بعدّة إشارات، من أقواها مادّة الهيستامين حين تلتصق بمستقبل خاصّ على تلك الخلايا يُسمّى مستقبل H2. يجلس الفاموتيدين على هذا المستقبل فيمنع الهيستامين من تنبيهه، فيقلّ إفراز الحمض ويرتفع حموضة المعدة قليلاً نحو الاعتدال، فتهدأ الحرقة ويُتاح للقرحة أن تلتئم. ولأنه يخفّف الإشارة ولا يوقف المضخّة النهائية للحمض كما تفعل مثبّطات مضخّة البروتون، فإن أثره أخفّ وأقصر منها لكنه يكفي كثيراً من الحالات. وهذا الطريق يفسّر لماذا يعمل ببطء أكبر من مضاد الحموضة الذي يعادل الحمض فوراً، وأسرع دواماً منه.',
    en: 'Cells in the stomach wall secrete acid, prompted by several signals, among the strongest of which is histamine when it attaches to a special receptor on those cells called the H2 receptor. Famotidine sits on this receptor and prevents histamine from stimulating it, so acid secretion falls and the stomach\'s acidity rises a little towards moderation, and heartburn calms and an ulcer is given a chance to heal. Because it reduces the signal and does not stop the final acid pump as proton-pump inhibitors do, its effect is gentler and shorter than theirs, but it suffices for many cases. This pathway explains why it works more slowly than an antacid that neutralises acid at once, and lasts longer than it.'
  },
  effects: {
    ar: 'يتحمّله أكثر الناس جيّداً، وأشيع آثاره القليلة صداع ودوار وإمساك أو إسهال. وقد يشعر بعضهم بتعب. وهو من أقلّ أدوية الحموضة إحداثاً للمشكلات، خاصة مقارنة بأدوية أقدم من فصيلته. ونادراً ما يسبّب اضطراباً في المزاج أو تشوّشاً، وهذا أقرب إلى الظهور عند كبار السنّ أو مرضى الكلى الذين يتراكم عندهم الدواء. وهذه الآثار في مجملها خفيفة وعابرة. لكن أهمّ ما ينبغي فهمه أن الفاموتيدين يخفّف عرض الحرقة، وقد يخفي بذلك علامة إنذار لمرض أخطر إذا أُطيل بلا تشخيص، ولهذا فإن استمرار الأعراض رغمه أهمّ من أثره الجانبي نفسه، وهو مفصّل في الحقل التالي.',
    en: 'Most people tolerate it well, and its few common effects are headache, dizziness and constipation or diarrhoea. Some may feel tired. It is among the least troublesome acid medicines, especially compared with older drugs of its family. It rarely causes a change of mood or confusion, and this is likelier in older people or those with kidney disease in whom the drug accumulates. On the whole these effects are mild and transient. But the most important thing to understand is that famotidine eases the symptom of heartburn, and may thereby hide a warning sign of a more serious disease if prolonged without a diagnosis, so the persistence of symptoms despite it matters more than its side effect itself, set out in the next field.'
  },
  warning: {
    ar: 'راجع الطبيب ولا تكتفِ بالدواء إذا استمرّت الحرقة أو عادت رغم أخذه، أو صاحبها فقدان وزن غير مقصود، أو صعوبة أو ألم عند البلع، أو قيء متكرّر، أو قيء دموي أو شبيه بحبيبات القهوة، أو براز أسود لزج، فهذه علامات إنذار لا تُكتَم بمضادّ حموضة. واطلب الإسعاف عند ألم صدر شديد ينتشر إلى الذراع أو الفكّ مع تعرّق وضيق نفس، فقد يُخطئ الناس بينه وبين الحرقة وهو قلب. واطلب الإسعاف عند علامات تحسّس شديد: تورّم الوجه والحلق وطفح متفقّع وضيق نفس. وراجع فوراً عند تشوّش أو هلوسة خاصة عند كبار السنّ ومرضى الكلى، وعند اصفرار العين أو الجلد.',
    en: 'See the doctor and do not settle for the medicine if heartburn persists or returns despite taking it, or is accompanied by unintended weight loss, difficulty or pain on swallowing, repeated vomiting, vomiting of blood or matter like coffee grounds, or black tarry stools, for these are warning signs not to be silenced by an acid medicine. Call an ambulance for severe chest pain spreading to the arm or jaw with sweating and breathlessness, which people may mistake for heartburn when it is the heart. Call an ambulance for signs of severe allergy: swelling of the face and throat, a blistering rash and breathlessness. Seek review at once for confusion or hallucinations, especially in older people and those with kidney disease, and for yellowing of the eyes or skin.'
  },
  interact: {
    ar: 'تعارضاته أقلّ بكثير من أدوية الحموضة الأقدم في فصيلته لأنه لا يعطّل إنزيمات الكبد كما تفعل هي. أهمّ ما يُنتبه له أن تقليله للحمض يغيّر امتصاص أدوية تحتاج وسطاً حمضيّاً، فقد يقلّ امتصاص بعض مضادات الفطريات كالكيتوكونازول والإيتراكونازول، وبعض أدوية السرطان والفيروسات، فتُباعد عنه أو يُقدّر الطبيب ذلك. ولا يُجمع عادة مع مثبّطات مضخّة البروتون بلا داعٍ لأنهما يعملان في الاتجاه نفسه. وأخبر الصيدلي إن كنت تأخذه بلا وصفة مع أدوية مزمنة، فحتى الدواء الذي يُصرف بلا وصفة قد يتداخل. ومرضى الكلى قد يحتاجون تعديلاً لأن الكلى تطرحه.',
    en: 'Its interactions are far fewer than the older acid medicines of its family, because it does not block liver enzymes as they do. The main concern is that its reduction of acid changes the absorption of drugs needing an acid medium, so the absorption of some antifungals such as ketoconazole and itraconazole, and some cancer and virus drugs, may fall, so they are spaced from it or the doctor accounts for it. It is not usually combined with proton-pump inhibitors without reason, since both work in the same direction. Tell the pharmacist if you take it without prescription alongside chronic medicines, since even a non-prescription drug may interact. People with kidney disease may need an adjustment, because the kidneys clear it.'
  },
  avoid: {
    ar: 'لا يأخذه من تحسّس منه أو من حاصرات H2 الأخرى. ويُستعمل بحذر مع تعديل عند مرضى الكلى الشديد لأنه يتراكم فيزيد خطر التشوّش، وعند كبار السنّ للسبب نفسه. وقبل الاعتماد عليه للحموضة المستمرّة تُستبعد أسباب أخطر بمراجعة الطبيب، خاصة عند من تجاوز سنّاً معيّنة أو ظهرت عنده علامات إنذار. وفي الحمل والرضاعة يُستعمل عند الحاجة بقرار الطبيب، وهو من الخيارات المدروسة نسبيّاً في هذا الباب لكنّ القرار يبقى طبّيّاً. ولا يُعطى للأطفال الصغار بلا وصفة. ومن يأخذه بلا وصفة لا يطيل استعماله أسابيع بلا مراجعة، لأن طول الحاجة إليه إشارة إلى مشكلة تستحقّ التشخيص لا مجرّد الكتم.',
    en: 'It is not for anyone allergic to it or to other H2 blockers. It is used with caution and adjustment in people with severe kidney disease because it accumulates and raises the risk of confusion, and in older people for the same reason. Before relying on it for persistent heartburn, more serious causes are ruled out by seeing the doctor, especially in anyone past a certain age or with warning signs. In pregnancy and breastfeeding it is used when needed by the doctor\'s decision, and it is among the relatively studied options in this area, but the decision remains medical. It is not given to young children without prescription. Anyone taking it without prescription does not prolong its use for weeks without review, since a long need for it signals a problem deserving diagnosis, not mere silencing.'
  },
  updated: '2026-09-25',
  src: [
    'https://medlineplus.gov/druginfo/meds/a687011.html',
    'https://www.nhs.uk/medicines/famotidine/'
  ]
};

RX_BODY['covid-vaccine'] = {
  what: {
    ar: 'لقاح كوفيد-١٩ مستحضر يدرّب جهاز المناعة على التعرّف على فيروس كورونا المستجدّ ومقاومته قبل أن يصيب الإنسان، فيخفّف شدّة المرض إن حدث. ليس دواءً يعالج عدوى قائمة بل وقاية تُعطى للأصحّاء. له عدّة أنواع تصل إلى الغاية نفسها بطرق مختلفة: لقاحات الرنا المرسال التي تحمل تعليمات لصنع بروتين الفيروس داخل الخلية، ولقاحات الناقل الفيروسي، ولقاحات الفيروس المعطّل أو البروتيني. يُعطى حقناً في العضل، وقد تُوصى جرعات معزّزة لتجديد الحماية مع الوقت ومع تغيّر سلالات الفيروس. وهو ركن من ركائز الوقاية إلى جانب النظافة والتهوية.',
    en: 'The COVID-19 vaccine is a preparation that trains the immune system to recognise and resist the novel coronavirus before it infects a person, so it lessens the severity of the disease if it occurs. It is not a medicine that treats an existing infection but a prevention given to the healthy. It has several kinds reaching the same end by different routes: messenger RNA vaccines that carry instructions to make the virus protein inside the cell, viral vector vaccines, and inactivated-virus or protein vaccines. It is given by injection into the muscle, and booster doses may be advised to renew protection over time and as the virus strains change. It is a pillar of prevention alongside hygiene and ventilation.'
  },
  why: {
    ar: 'يُعطى للوقاية من كوفيد-١٩، وهدفه الأول تقليل المرض الشديد والدخول للمستشفى والوفاة، لا منع كل عدوى منعاً تامّاً، فقد يُصاب الملقّح لكن بصورة أخفّ غالباً. يُوصى به خاصّة لمن هم أكثر عرضة للمضاعفات: كبار السنّ، وأصحاب الأمراض المزمنة كالقلب والرئة والسكّري والكلى، وضعاف المناعة، والحوامل بقرار طبّي، والعاملين في الرعاية الصحّية. وتُوصى جرعات معزّزة موسميّة لفئات معيّنة لأن الحماية تضعف مع الوقت وتتغيّر السلالات. الغاية مجتمعيّة أيضاً: تقليل انتشار الفيروس وحماية من حولك ممّن قد لا يقوى على المرض. وهو لا يعالج من مرض فعلاً بل يقي قبل الإصابة.',
    en: 'It is given to prevent COVID-19, its first aim being to reduce severe disease, hospitalisation and death, not to prevent every infection completely, for a vaccinated person may still catch it but usually more mildly. It is advised especially for those most exposed to complications: older people, those with chronic diseases such as heart, lung, diabetes and kidney disease, the immunocompromised, pregnant women by medical decision, and healthcare workers. Seasonal booster doses are advised for certain groups because protection weakens over time and the strains change. Its aim is also communal: reducing the spread of the virus and protecting those around you who may not withstand the disease. It does not treat someone already ill but prevents before infection.'
  },
  how: {
    ar: 'يتعرّف جهاز المناعة على الأعداء بأشكالها المميّزة، ولفيروس كورونا بروتين ناتئ على سطحه يُسمّى الشوكة يستعمله للدخول إلى الخلايا. تُعرّف اللقاحات المناعة على هذا البروتين بطرق مختلفة: لقاح الرنا المرسال يوصل تعليمات مؤقّتة تجعل خلايا الجسم تصنع نسخة من بروتين الشوكة وحده، ولقاح الناقل يستعمل فيروساً غير ضارّ ليحمل هذه التعليمات، ولقاح البروتين يعطي البروتين جاهزاً. في كل الحالات يرى الجهاز المناعي الشوكة فيصنع أجساماً مضادّة وخلايا ذاكرة دون أن يمرض الإنسان. فإذا جاءه الفيروس الحقيقي لاحقاً عرفه بسرعة وهاجمه قبل أن يستفحل. وتعليمات الرنا لا تدخل نواة الخلية ولا تغيّر الجينات، وتتحلّل سريعاً بعد أداء مهمّتها.',
    en: 'The immune system recognises enemies by their distinctive shapes, and the coronavirus has a protein jutting from its surface called the spike, which it uses to enter cells. The vaccines teach immunity about this protein by different routes: the messenger RNA vaccine delivers temporary instructions that make the body\'s cells produce a copy of the spike protein alone, the vector vaccine uses a harmless virus to carry these instructions, and the protein vaccine gives the protein ready-made. In every case the immune system sees the spike and makes antibodies and memory cells without the person falling ill. So if the real virus comes later, it recognises it quickly and attacks it before it takes hold. The RNA instructions do not enter the cell nucleus or change the genes, and they break down soon after doing their task.'
  },
  effects: {
    ar: 'أشيع آثاره خفيفة وعابرة وتزول خلال أيام، وهي علامة على أن الجسم يبني مناعته: ألم واحمرار وتورّم في موضع الحقنة، وتعب، وصداع، وأوجاع عضلية ومفصلية، وقشعريرة، وحرارة خفيفة، وغثيان أحياناً، وتضخّم مؤقّت في غدّة ليمفية قرب موضع الحقن. وتُخفَّف بالراحة وشرب السوائل وكمّادة باردة على الموضع وخافض حرارة بسيط عند الحاجة. وهذه الآثار المتوقّعة أخفّ بكثير من مضاعفات المرض نفسه. لكن هناك آثاراً نادرة جدّاً لكنها مهمّة تستدعي مراجعة أو إسعافاً، مفصّلة في الحقل التالي، والفارق بين انزعاج يومين وعلامة تحتاج طبيباً يجب أن يكون واضحاً لكل من يتلقّى اللقاح.',
    en: 'Its commonest effects are mild, transient and gone within days, and they are a sign the body is building its immunity: pain, redness and swelling at the injection site, tiredness, headache, muscle and joint aches, chills, a mild fever, sometimes nausea, and temporary swelling of a lymph gland near the injection site. They are eased by rest, drinking fluids, a cold compress on the site and a simple fever-reducer when needed. These expected effects are far milder than the complications of the disease itself. But there are very rare yet important effects that call for review or an ambulance, set out in the next field, and the difference between a two-day nuisance and a sign needing a doctor must be clear to everyone who receives the vaccine.'
  },
  warning: {
    ar: 'اطلب الإسعاف فوراً عند علامات تحسّس شديد بعد اللقاح، وأغلبها يظهر خلال دقائق: تورّم الوجه أو الشفتين أو اللسان أو الحلق، ضيق نفس أو أزيز، طفح منتشر، دوخة شديدة أو إغماء، وتسارع نبض؛ ولهذا يُطلب البقاء تحت الملاحظة مدّة قصيرة بعد الحقنة. وراجع فوراً عند ألم صدر أو ضيق نفس أو خفقان أو شعور برفرفة القلب خاصة عند الشباب في الأيام الأولى، فقد رُبطت ببعض اللقاحات حالات نادرة من التهاب عضلة القلب أو غشائه. واطلب الإسعاف عند صداع شديد مستمرّ أو تغيّم رؤية أو ضيق نفس أو تورّم ساق أو كدمات وبقع دم صغيرة بعد أيام إلى أسبوعين، فقد تنذر بجلطة نادرة مع نقص صفيحات. وأيّ عرض عصبي جديد كضعف أو خدر يستدعي الطبيب.',
    en: 'Call an ambulance at once for signs of severe allergy after the vaccine, most appearing within minutes: swelling of the face, lips, tongue or throat, breathlessness or wheeze, a spreading rash, severe dizziness or fainting, and a racing pulse; this is why a short period of observation after the injection is asked for. Seek review at once for chest pain, breathlessness, palpitations or a fluttering heart, especially in young people in the first days, since rare cases of inflammation of the heart muscle or its membrane have been linked to some vaccines. Call an ambulance for a severe persistent headache, blurred vision, breathlessness, a swollen leg, or bruising and small blood spots days to a fortnight later, which may herald a rare clot with low platelets. Any new nerve symptom such as weakness or numbness needs the doctor.'
  },
  interact: {
    ar: 'لا تعارض دوائي مهمّ يمنع أغلب الناس من أخذه، ويمكن عادة إعطاؤه مع لقاحات أخرى كلقاح الإنفلونزا بقرار الجهة الصحّية. من يأخذ مميّعات الدم أو عنده اضطراب نزف يُخبر من يعطيه اللقاح حتى يُضغط الموضع جيّداً بعد الحقن ويُختار إبرة رفيعة، ولا يُوقف المميّع من تلقاء المريض. ومن يأخذ أدوية تثبّط المناعة أو الكورتيزون بجرعات عالية قد تكون استجابته للقاح أضعف، فيُنسّق التوقيت مع الطبيب لينال أفضل حماية ممكنة. وخافض الحرارة يُؤخذ لعلاج الأعراض بعد اللقاح لا لمنعها قبله روتينيّاً. أخبر من يعطيك اللقاح بأمراضك وأدويتك وأيّ تحسّس شديد سابق لجرعة لقاح أو أحد مكوّناته.',
    en: 'There is no major drug interaction that stops most people from having it, and it can usually be given with other vaccines such as the flu vaccine by the health authority\'s decision. Anyone taking blood thinners or with a bleeding disorder tells the person giving the vaccine so the site is pressed well after the injection and a fine needle is chosen, and does not stop the thinner on their own. Anyone taking immune-suppressing drugs or high-dose corticosteroids may respond to the vaccine more weakly, so the timing is coordinated with the doctor to gain the best possible protection. A fever-reducer is taken to treat symptoms after the vaccine, not routinely to prevent them beforehand. Tell the person giving the vaccine your diseases, medicines and any previous severe allergy to a vaccine dose or one of its components.'
  },
  avoid: {
    ar: 'لا يأخذه من أصابه تحسّس شديد بعد جرعة سابقة من اللقاح نفسه أو من أحد مكوّناته المعروفة، ويُقيَّم مثل هذا الشخص عند مختصّ الحساسية. ومن يمرض مرضاً حادّاً مع حرارة عالية يؤجّل اللقاح حتى يتعافى، أمّا الزكام البسيط فلا يمنع. وضعاف المناعة يأخذونه بقرار طبّي لأنهم من أحوج الناس للوقاية وإن كانت استجابتهم أضعف. والحامل والمرضع تأخذانه عند التوصية به لأن فائدته تفوق خطره في الجائحة، والقرار مع الطبيب. ومن أصيب بالتهاب قلب أو جلطة نادرة نُسبت للقاح سابق يُقيَّم قبل أيّ جرعة تالية. ويبقى تحت الملاحظة مدّة قصيرة بعد الحقنة تحسّباً لتفاعل فوري، ويُخبر مقدّم اللقاح بكل سوابقه الصحّية.',
    en: 'It is not for anyone who had a severe allergy after a previous dose of the same vaccine or one of its known components, and such a person is assessed by an allergy specialist. Anyone with an acute illness and high fever postpones the vaccine until recovery, while a simple cold does not prevent it. The immunocompromised receive it by medical decision, since they are among those most in need of protection even if their response is weaker. A pregnant or breastfeeding woman receives it when advised, because its benefit outweighs its risk in a pandemic, and the decision is with the doctor. Anyone who had heart inflammation or a rare clot attributed to a previous vaccine is assessed before any later dose. The person stays under observation a short while after the injection in case of an immediate reaction, and tells the vaccine provider all their health history.'
  },
  updated: '2026-09-25',
  src: [
    'https://www.who.int/emergencies/diseases/novel-coronavirus-2019/covid-19-vaccines',
    'https://www.cdc.gov/covid/vaccines/index.html',
    'https://www.nhs.uk/vaccinations/covid-19-vaccine/'
  ]
};
